function header(){document.body.classList.add('mc');return '<header class="lab-header mc-head">'+ic('logo','mc-logo')+ProductShell.brand+(isHome&&model?homeScope():'')+ProductShell.nav(isHome?'home':'management','lab-topnav')+'</header>'}
function bottom(){return ProductShell.nav(isHome?'home':'management','lab-bottom mc-nav')}
