function loadingPriceBasis(){return dataStatus.prices==='checking'?'확인 중':priceBasis}
function loading(){if(app.querySelector('.loading-screen')){for(const k of ['prices','dividends','ledger']){const row=app.querySelector('[data-loading-state="'+k+'"]'),b=row.querySelector('b');b.textContent=statusText[dataStatus[k]];b.className=dataStatus[k]==='confirmed'?'confirmed':'';row.dataset.state=dataStatus[k];app.querySelector('.mc-step[data-step="'+k+'"]').dataset.state=dataStatus[k]}app.querySelector('#loading-price-basis').textContent=loadingPriceBasis();app.querySelector('#loading-distribution-basis').textContent=distributionBasis;return}const rows={prices:'시장가격 확인',dividends:'분배금 확인',ledger:'내 배당 기록 정리'};app.innerHTML=header()+'<main class="loading-screen mc-load" aria-live="polite"><h1 class="loading-title">돈냄새연구소의<br><span>월배당 ETF</span> 바이블</h1><p class="mc-l-sub">작은 씨앗이, 꾸준한 배당의 숲이 되는 길<br>함께 만들어가요.</p><img class="mc-l-tree" src="'+A+'loading_sapling.webp" alt="" aria-hidden="true"><section class="mc-l-card"><p class="loading-message"><strong>내 배당 농장을 점검하고 있어요.</strong><span>잠시만 기다려주세요. 더 정확한 분석을 위해<br>최신 데이터를 확인하고 있어요.</span></p><div class="loading-checks">'+Object.entries(rows).map(([k,t])=>'<div class="loading-state" data-loading-state="'+k+'" data-state="'+dataStatus[k]+'"><i class="mc-st" aria-hidden="true"></i><span>'+t+'</span><b class="'+(dataStatus[k]==='confirmed'?'confirmed':'')+'">'+statusText[dataStatus[k]]+'</b></div>').join('')+'<div class="mc-steps" aria-hidden="true">'+Object.keys(rows).map(k=>'<i class="mc-step" data-step="'+k+'" data-state="'+dataStatus[k]+'"></i>').join('')+'</div></div></section><ul class="loading-foot mc-l-foot"><li>'+ic('calendar')+'<span>시장가격 기준 <span id="loading-price-basis">'+esc(loadingPriceBasis())+'</span></span></li><li>'+ic('doc')+'<span>분배금 자료 기준일 <span id="loading-distribution-basis">'+esc(distributionBasis)+'</span></span></li><li>'+ic('cloud')+'<span>실패·오프라인에도 저장 기록으로 진입</span></li></ul></main>'}
