function sharedCash(){if(scope.kind!=='instrument')return '';const ids=[...new Set(state.transactions.filter(t=>t.code===scope.id).map(t=>t.account_id))];return '<div class="mc-shared"><p class="record-note">종목 평가액에는 계좌 공유 배당현금을 배분하지 않습니다.</p>'+ids.map(a=>'<p class="warm record-note">'+esc(state.accounts.find(x=>x.account_id===a)?.name)+' 공유 배당현금: '+won(model.cash.get(a))+'</p>').join('')+'</div>'}
function breakdown(p){const inst=scope.kind==='instrument';return '<section class="value-breakdown mc-bd"><h2>현재가치 분해</h2><div class="breakdown value-segments mc-chips'+(inst?' mc-chips-2':'')+'"><div class="value-segment direct-value"><span>직접매수</span><b>'+amount(p,p.direct).replace(/원/,'')+'</b></div><i aria-hidden="true">+</i><div class="value-segment reinvest-value"><span>재투자</span><b>'+amount(p,p.reinvest).replace(/원/,'')+'</b></div>'+(inst?'':'<i aria-hidden="true">+</i><div class="value-segment cash-value"><span>배당현금</span><b>'+won(p.cash).replace(/원/,'')+'</b></div>')+'</div><div class="total mc-total"><span class="sr-only">'+(inst?'종목 평가액':'합계')+'</span><b>= '+amount(p,p.total)+'</b></div>'+sharedCash()+'</section>'}
